package com.android.tools.lint.checks;

import com.android.SdkConstants;
import com.android.resources.ResourceType;
import com.android.tools.lint.client.api.ResourceUrl;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Collections;
import java.util.List;
import org.w3c.dom.Element;

public class DuplicateResourceDetector extends Detector implements Detector.XmlScanner {

    public static final Issue ISSUE = Issue.create(
            "ReferenceType",
            "Incorrect reference type",
            "When you generate a resource alias, the resource you are pointing to must be "
                    + "of the same type as the alias.",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            new Implementation(DuplicateResourceDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public List<String> getApplicableElements() {
        return Collections.singletonList(SdkConstants.TAG_ITEM);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String type = element.getAttributeNS(null, SdkConstants.ATTR_TYPE);
        if (type == null || type.isEmpty()) {
            return;
        }

        String value = element.getTextContent();
        if (value == null) {
            return;
        }
        value = value.trim();
        if (value.isEmpty()) {
            return;
        }

        ResourceUrl url = ResourceUrl.parse(value, true);
        if (url == null || url.type == null) {
            return;
        }

        if (!type.equalsIgnoreCase(url.type.getName())) {
            String message = String.format(
                    "Alias type (%1$s) does not match referenced resource type (%2$s)",
                    type, url.type.getName());
            context.report(ISSUE, element, context.getLocation(element), message);
        }
    }
}
```

