private static String getReferenceType(String value) {
    if (value == null || value.length() < 2 || !value.startsWith("@") || value.startsWith("@@")) {
        return null;
    }
    String ref = value.substring(1);
    if (ref.startsWith("+")) {
        ref = ref.substring(1);
    }
    if (ref.startsWith("*")) {
        ref = ref.substring(1);
    }
    int slash = ref.indexOf('/');
    if (slash <= 0 || slash == ref.length() - 1) {
        return null;
    }
    int colon = ref.lastIndexOf(':', slash);
    String type;
    if (colon >= 0) {
        type = ref.substring(colon + 1, slash);
    } else {
        type = ref.substring(0, slash);
    }
    return type.isEmpty() ? null : type;
}
